import { BaseException } from '../../base-exception';
import { Locale } from '../../locale';

export class GenericDisconnectionException extends BaseException {
    constructor(reason: string) {
        super(
            'Game.GenericServerDisconnection',
            `Game server sent unhandled disconnection message with reason "${reason}"`
        );

    }

    public localise(locale: Locale) {
        this.buttonText = this.getButtonText(locale);

        switch (locale) {
            case 'it-it':
                this.displayMessage = 'Sei stato disconnesso dal gioco, per favore chiudi il gioco e riaprilo';
                break;
            case 'es-es':
                this.displayMessage = '¡Vaya! Algo ha salido mal. Vuelve a conectarte e inténtalo de nuevo.';
                break;
            default:
                this.displayMessage = 'Oops! It looks like something went wrong. Please reconnect and try again.';
                break;
        }
    }
}
